CREATE TABLE IF NOT EXISTS clients(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,meta_business_id VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS phone_numbers(id BIGINT AUTO_INCREMENT PRIMARY KEY,client_id BIGINT,phone_number_id VARCHAR(40),display_phone VARCHAR(40),waba_id VARCHAR(40),status VARCHAR(24) DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events(id BIGINT AUTO_INCREMENT PRIMARY KEY,client_id BIGINT,phone_number_id VARCHAR(40),contact_wa_id VARCHAR(40),event_name VARCHAR(60),message_id VARCHAR(140),occurred_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_message_event(message_id,event_name));
CREATE TABLE IF NOT EXISTS event_mappings(id BIGINT AUTO_INCREMENT PRIMARY KEY,client_id BIGINT,event_name VARCHAR(60),platform VARCHAR(30),platform_event VARCHAR(80),active TINYINT DEFAULT 1,UNIQUE KEY uq_mapping(client_id,event_name,platform));
